const listUnjustifiedAccessWindows = `-- name: ListUnjustifiedAccessWindows :many
SELECT e.id AS access_id, e.customer_id, e.product_id,
       e.source_type, e.source_id, e.starts_at, e.ends_at,
       pay.id AS payment_id,
       paid_line.product_id AS payment_product_id,
       CASE
           WHEN e.source_type = 'subscription' AND s.id IS NULL THEN 'missing_subscription'
           ELSE 'refunded_payment'
       END::text AS cause
FROM billing.product_access e
LEFT JOIN billing.subscriptions s
       ON e.source_type = 'subscription' AND s.id::text = e.source_id AND s.merchant_id = e.merchant_id AND s.deleted_at IS NULL
LEFT JOIN billing.payments pay
       ON e.source_type = 'purchase' AND pay.id = e.payment_id AND pay.merchant_id = e.merchant_id AND pay.deleted_at IS NULL
LEFT JOIN LATERAL (SELECT l.product_id FROM billing.order_lines l
       WHERE l.merchant_id=e.merchant_id AND l.order_id=pay.order_id AND l.product_id=e.product_id
       LIMIT 1) paid_line ON true
LEFT JOIN LATERAL (SELECT true AS settled FROM billing.payments r
       WHERE r.merchant_id = pay.merchant_id AND r.refunded_payment_id = pay.id
         AND r.deleted_at IS NULL AND r.status = 'succeeded'
         AND r.amount < 0 AND r.reversal_kind = 'refund'
       LIMIT 1) refund ON true
WHERE e.merchant_id = $1::uuid
  AND ($2::uuid IS NULL OR e.customer_id = $2::uuid)
  AND e.revoked_at IS NULL AND e.deleted_at IS NULL
  AND e.starts_at <= $3::timestamptz
  AND (e.ends_at IS NULL OR e.ends_at > $3::timestamptz)
  AND e.source_type IN ('subscription', 'purchase')
  -- no live un-terminated access grant covering now justifies the window
  AND NOT EXISTS (
      SELECT 1 FROM billing.grants g
      WHERE g.merchant_id = e.merchant_id
        AND g.customer_id = e.customer_id
        AND g.event = 'grant' AND g.kind = 'access'
        AND (g.id = e.grant_id OR (g.source_id = e.source_id AND g.source_type = e.source_type))
        AND g.starts_at <= $3::timestamptz
        AND (g.ends_at IS NULL OR g.ends_at > $3::timestamptz)
        AND NOT EXISTS (
            SELECT 1 FROM billing.grants t
            WHERE t.merchant_id = g.merchant_id AND t.supersedes_id = g.id
              AND t.event IN ('revoke', 'expire', 'supersede'))
  )
  -- a TERMINATED backing grant means derive.grant_effect.excess owns the retraction
  AND NOT EXISTS (
      SELECT 1 FROM billing.grants tg
      JOIN billing.grants t ON t.merchant_id = tg.merchant_id AND t.supersedes_id = tg.id
                             AND t.event IN ('revoke', 'expire', 'supersede')
      WHERE tg.merchant_id = e.merchant_id AND tg.id = e.grant_id
  )
  AND (
      (e.source_type = 'subscription' AND s.id IS NULL)
      OR (e.source_type = 'purchase' AND pay.id IS NOT NULL
          AND (pay.status = 'refunded' OR refund.settled))
  )
ORDER BY e.starts_at, e.id
LIMIT $4::int
`

type ListUnjustifiedAccessWindowsParams struct {
	MerchantID uuid.UUID
	CustomerID *uuid.UUID
	Now        time.Time
	RowLimit   int32
}

type ListUnjustifiedAccessWindowsRow struct {
	AccessID         uuid.UUID
	CustomerID       uuid.UUID
	ProductID        uuid.UUID
	SourceType       string
	SourceID         string
	StartsAt         time.Time
	EndsAt           *time.Time
	PaymentID        *uuid.UUID
	PaymentProductID *uuid.UUID
	Cause            string
}

// derive.access.unjustified (freeloader): a live window whose source is proven
// absent or reversed: missing_subscription or refunded_payment. Never fires while
// a live access grant covers now (a live window past paid-through is normal for
// auto-renew), nor when the backing grant is terminated
// (derive.grant_effect.excess's). Surface-only: revoking access is an operator
// decision. NULL customer_id = merchant-wide.
// Oldest window first, capped: truncation delays an operator decision rather
// than losing one.
func (q *Queries) ListUnjustifiedAccessWindows(ctx context.Context, arg ListUnjustifiedAccessWindowsParams) ([]ListUnjustifiedAccessWindowsRow, error) {
	rows, err := q.db.Query(ctx, listUnjustifiedAccessWindows,
		arg.MerchantID,
		arg.CustomerID,
		arg.Now,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUnjustifiedAccessWindowsRow
	for rows.Next() {
		var i ListUnjustifiedAccessWindowsRow
		if err := rows.Scan(
			&i.AccessID,
			&i.CustomerID,
			&i.ProductID,
			&i.SourceType,
			&i.SourceID,
			&i.StartsAt,
			&i.EndsAt,
			&i.PaymentID,
			&i.PaymentProductID,
			&i.Cause,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

