const upsertReconciliationFinding = `-- name: UpsertReconciliationFinding :one
INSERT INTO billing.reconciliation_findings (
    merchant_id, finding_type, subject_key, severity, status,
    recommended_action, evidence, resolved_at, resolution,
    first_seen_run, last_seen_run, psp_id, rail, change, source, evidence_digest, pull_id
) VALUES (
    $1, $2, $3,
    $4, $5, $6,
    $7::jsonb,
    CASE WHEN $5::text = 'auto_fixed' THEN now() ELSE NULL END,
    CASE WHEN $5::text = 'auto_fixed' THEN 'enforced' ELSE NULL END,
    $8, $8, $9::uuid,
    -- A pull finding carries its PSP's rail (the psps FK checks they agree).
    (SELECT p.rail FROM billing.psps p WHERE p.merchant_id = $1 AND p.id = $9::uuid),
    $10::jsonb, $11::text, $12::text, $13::uuid
)
ON CONFLICT (merchant_id, finding_type, psp_id, subject_key) DO UPDATE SET
    -- The latest import whose pull saw the finding.
    pull_id = COALESCE(EXCLUDED.pull_id, billing.reconciliation_findings.pull_id),
    severity = EXCLUDED.severity,
    status = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest OR billing.reconciliation_findings.resolution = 'foreign') THEN 'ignored'
        ELSE EXCLUDED.status
    END,
    recommended_action = EXCLUDED.recommended_action,
    evidence = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest) THEN billing.reconciliation_findings.evidence
        ELSE EXCLUDED.evidence
    END,
    change = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest) THEN billing.reconciliation_findings.change
        ELSE EXCLUDED.change
    END,
    evidence_digest = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest) THEN billing.reconciliation_findings.evidence_digest
        ELSE EXCLUDED.evidence_digest
    END,
    source = COALESCE(EXCLUDED.source, billing.reconciliation_findings.source),
    resolved_at = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest OR billing.reconciliation_findings.resolution = 'foreign') THEN billing.reconciliation_findings.resolved_at
        WHEN EXCLUDED.status = 'auto_fixed' THEN EXCLUDED.resolved_at
        ELSE NULL
    END,
    resolution = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest OR billing.reconciliation_findings.resolution = 'foreign') THEN billing.reconciliation_findings.resolution
        WHEN EXCLUDED.status = 'auto_fixed' THEN EXCLUDED.resolution
        ELSE NULL
    END,
    -- A reopened finding is a new episode: the previous resolver and
    -- approval run belong to the episode they closed.
    resolved_by = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest OR billing.reconciliation_findings.resolution = 'foreign') THEN billing.reconciliation_findings.resolved_by
        WHEN billing.reconciliation_findings.resolved_at IS NULL THEN billing.reconciliation_findings.resolved_by
        ELSE NULL
    END,
    approval_run_id = NULL,
    -- An inline auto_fixed is a resolution: clear the notify linkage so a
    -- reopen of this identity notifies again.
    notified_at = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest OR billing.reconciliation_findings.resolution = 'foreign') THEN billing.reconciliation_findings.notified_at
        WHEN EXCLUDED.status = 'auto_fixed' THEN NULL
        ELSE billing.reconciliation_findings.notified_at
    END,
    notified_severity = CASE
        WHEN billing.reconciliation_findings.status = 'ignored'
             AND (EXCLUDED.evidence_digest IS NULL OR billing.reconciliation_findings.evidence_digest IS NOT DISTINCT FROM EXCLUDED.evidence_digest OR billing.reconciliation_findings.resolution = 'foreign') THEN billing.reconciliation_findings.notified_severity
        WHEN EXCLUDED.status = 'auto_fixed' THEN NULL
        ELSE billing.reconciliation_findings.notified_severity
    END,
    last_seen_run = COALESCE(EXCLUDED.last_seen_run, billing.reconciliation_findings.last_seen_run),
    last_seen_at = now(),
    updated_at = now()
WHERE NOT ($14::boolean AND billing.reconciliation_findings.pull_id IS NOT NULL)
RETURNING id, merchant_id, finding_type, rail, psp_id, subject_key, severity, status, recommended_action, first_seen_run, last_seen_run, last_seen_at, resolved_at, resolution, operator_notes, created_at, updated_at, evidence, resolved_by, notified_at, notified_severity, seen_run_class, change, source, evidence_digest, approval_run_id, pull_id, dismissed_at
`

type UpsertReconciliationFindingParams struct {
	MerchantID        uuid.UUID
	FindingType       string
	SubjectKey        string
	Severity          string
	Status            string
	RecommendedAction *string
	Evidence          []byte
	RunID             *uuid.UUID
	PspID             *uuid.UUID
	Change            []byte
	Source            *string
	EvidenceDigest    *string
	PullID            *uuid.UUID
	DeferToPull       bool
}

// Re-runs UPDATE the standing finding for (merchant, finding_type, subject_key).
// A previously resolved finding that reappears is REOPENED with the freshly
// computed status; an ignored finding stays ignored (an operator explicitly
// silenced this identity), unless it is a dismissed proposal whose provider
// evidence now differs (evidence_digest).
// An ignored finding stays ignored while its evidence is unchanged; one resolved
// as foreign stays so whatever the provider record later reads (evidence still
// refreshes).
// A finding a pull raised is the import's: a writer naming no pull leaves it
// (defer_to_pull), and gets no row back.
func (q *Queries) UpsertReconciliationFinding(ctx context.Context, arg UpsertReconciliationFindingParams) (BillingReconciliationFinding, error) {
	row := q.db.QueryRow(ctx, upsertReconciliationFinding,
		arg.MerchantID,
		arg.FindingType,
		arg.SubjectKey,
		arg.Severity,
		arg.Status,
		arg.RecommendedAction,
		arg.Evidence,
		arg.RunID,
		arg.PspID,
		arg.Change,
		arg.Source,
		arg.EvidenceDigest,
		arg.PullID,
		arg.DeferToPull,
	)
	var i BillingReconciliationFinding
	err := row.Scan(
		&i.ID,
		&i.MerchantID,
		&i.FindingType,
		&i.Rail,
		&i.PspID,
		&i.SubjectKey,
		&i.Severity,
		&i.Status,
		&i.RecommendedAction,
		&i.FirstSeenRun,
		&i.LastSeenRun,
		&i.LastSeenAt,
		&i.ResolvedAt,
		&i.Resolution,
		&i.OperatorNotes,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Evidence,
		&i.ResolvedBy,
		&i.NotifiedAt,
		&i.NotifiedSeverity,
		&i.SeenRunClass,
		&i.Change,
		&i.Source,
		&i.EvidenceDigest,
		&i.ApprovalRunID,
		&i.PullID,
		&i.DismissedAt,
	)
	return i, err
}

const upsertReconciliationState = `-- name: UpsertReconciliationState :one

INSERT INTO billing.reconciliation_state (
    merchant_id, source_domain, fully_reconciled, updated_at
) VALUES (
    $1::uuid, $2::text,
    $3::boolean, now()
)
ON CONFLICT (merchant_id, source_domain) DO UPDATE SET
    fully_reconciled = EXCLUDED.fully_reconciled,
    updated_at = now()
RETURNING merchant_id, source_domain, fully_reconciled, updated_at
`

type UpsertReconciliationStateParams struct {
	MerchantID      uuid.UUID
	SourceDomain    string
	FullyReconciled bool
}

// The per-(merchant, source_domain) confirmed-absence gate.
// reconcile.MarkReconciledSourceDomains sets it once a pull proves exhaustive
// coverage of every PSP whose rail could hold the domain's sources. No pull
// proves the local-sourced grants domain; it stays a manual decision. Pulls
// never unset the flag.
// Mark a source domain's reconciliation watermark: pass fully_reconciled=true
// after a completed authoritative pull/import for that domain.
func (q *Queries) UpsertReconciliationState(ctx context.Context, arg UpsertReconciliationStateParams) (BillingReconciliationState, error) {
	row := q.db.QueryRow(ctx, upsertReconciliationState, arg.MerchantID, arg.SourceDomain, arg.FullyReconciled)
	var i BillingReconciliationState
	err := row.Scan(
		&i.MerchantID,
		&i.SourceDomain,
		&i.FullyReconciled,
		&i.UpdatedAt,
	)
	return i, err
}
